import { Card, Image, Text, Group, Badge, Button, Stack } from "@mantine/core";
import { IconExternalLink, IconBrandGithub } from "@tabler/icons-react";

const ProjectCard = ({ project }) => {
  const handleExternalLink = (url) => {
    if (url) {
      window.open(url, "_blank", "noopener,noreferrer");
    }
  };

  return (
    <Card
      style={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        transition: "transform 0.2s ease, box-shadow 0.2s ease"
      }}
    >
      <Card.Section>
        <Image
          src={project.image}
          alt={project.title}
          height={200}
          style={{
            objectFit: "cover",
            borderTopLeftRadius: "var(--mantine-radius-lg)",
            borderTopRightRadius: "var(--mantine-radius-lg)"
          }}
        />
      </Card.Section>

      <Stack gap="sm" style={{ flex: 1, padding: "1rem" }}>
        <Text style={{ fontWeight: 600, fontSize: "1.25rem" }}>{project.title}</Text>

        <Text size="sm" c="gray.6" lineClamp={3}>
          {project.description}
        </Text>

        <Group gap="xs" style={{ flexWrap: "wrap" }}>
          {project.technologies.map((tech) => (
            <Badge
              key={tech}
              variant="light"
              color="blue"
              size="sm"
            >
              {tech}
            </Badge>
          ))}
        </Group>
      </Stack>

      <Group gap="sm" style={{ padding: "0 1rem 1rem" }}>
        {project.liveUrl && (
          <Button
            leftSection={<IconExternalLink size={16} />}
            variant="filled"
            size="sm"
            onClick={() => handleExternalLink(project.liveUrl)}
          >
            Live Demo
          </Button>
        )}

        {project.githubUrl && (
          <Button
            leftSection={<IconBrandGithub size={16} />}
            variant="outline"
            size="sm"
            onClick={() => handleExternalLink(project.githubUrl)}
          >
            GitHub
          </Button>
        )}
      </Group>
    </Card>
  );
};

export default ProjectCard;

import { ActionIcon } from "@mantine/core";
import { IconSun, IconMoon } from "@tabler/icons-react";
import { useTheme } from "../../context/ThemeContext";

const ThemeToggle = ({ size = "lg" }) => {
  const { colorScheme, toggleColorScheme } = useTheme();
  const iconSize = size === "sm" ? 18 : size === "lg" ? 22 : 20;

  return (
    <ActionIcon
      onClick={toggleColorScheme}
      size={size}
      variant="subtle"
      color="gray.7"
      aria-label="Toggle color scheme"
      style={{
        transition: "color 0.2s ease, transform 0.2s ease"
      }}
    >
      {colorScheme === "dark" ? (
        <IconSun size={iconSize} />
      ) : (
        <IconMoon size={iconSize} />
      )}
    </ActionIcon>
  );
};

export default ThemeToggle;

import { Container, Title, Text, Group, Stack, Paper, Badge, Button, Box } from "@mantine/core";
import { IconDownload, IconCheck } from "@tabler/icons-react";
import { siteContent } from "../../data/siteContent";
import SocialLinks from "../common/SocialLinks";

const AboutSection = () => {
  return (
    <Box
      id="about"
      style={{
        padding: "6rem 0",
        backgroundColor: "var(--mantine-color-gray-0)"
      }}
    >
      <Container size="lg">
        <Stack gap="xl">
          <Stack gap="xs" style={{ textAlign: "center" }}>
            <Title order={2} style={{ fontSize: "2.5rem", fontWeight: 700 }}>
              About Me
            </Title>
            <Text c="gray.6" size="lg" style={{ maxWidth: "600px", margin: "0 auto" }}>
              Get to know the engineer behind the code
            </Text>
          </Stack>

          <Paper
            shadow="md"
            radius="lg"
            style={{
              padding: "3rem",
              backgroundColor: "var(--mantine-color-body)"
            }}
          >
            <Group align="flex-start" gap="xl" style={{ flexDirection: "row" }}>
              <Stack gap="lg" style={{ flex: 1 }}>
                {siteContent.about.bio.map((paragraph, index) => (
                  <Text key={index} size="lg" style={{ lineHeight: 1.7 }}>
                    {paragraph}
                  </Text>
                ))}

                <Stack gap="sm" style={{ marginTop: "1rem" }}>
                  {siteContent.about.highlights.map((highlight, index) => (
                    <Group key={index} gap="sm">
                      <Badge color="green" size="lg" variant="filled" style={{ minWidth: "32px", height: "24px" }}>
                        <IconCheck size={14} />
                      </Badge>
                      <Text size="md">{highlight}</Text>
                    </Group>
                  ))}
                </Stack>

                <Group gap="lg" style={{ marginTop: "2rem" }}>
                  <Button
                    component="a"
                    href={siteContent.personal.resumeUrl}
                    download
                    leftSection={<IconDownload size={18} />}
                    size="md"
                    style={{
                      background: "linear-gradient(135deg, #3B82F6 0%, #8B5CF6 100%)",
                      border: "none"
                    }}
                  >
                    Download Resume
                  </Button>

                  <SocialLinks links={siteContent.socialLinks} />
                </Group>
              </Stack>
            </Group>
          </Paper>
        </Stack>
      </Container>
    </Box>
  );
};

export default AboutSection;

import { Container, Title, Text, SimpleGrid, Group, Badge, Button, Box, Stack, Image, Modal } from "@mantine/core";
import { IconExternalLink, IconBrandGithub, IconFilter } from "@tabler/icons-react";
import { useState } from "react";
import { siteContent } from "../../data/siteContent";
import ProjectCard from "../common/ProjectCard";

const ProjectsSection = () => {
  const [activeCategory, setActiveCategory] = useState("all");
  const [modalOpened, setModalOpened] = useState(false);
  const [selectedProject, setSelectedProject] = useState(null);

  const categories = [
    { value: "all", label: "All Projects" },
    { value: "fullstack", label: "Full Stack" },
    { value: "frontend", label: "Frontend" },
    { value: "backend", label: "Backend" },
    { value: "mobile", label: "Mobile" },
    { value: "devops", label: "DevOps" }
  ];

  const filteredProjects = activeCategory === "all"
    ? siteContent.projects
    : siteContent.projects.filter(p => p.category === activeCategory);

  const handleProjectClick = (project) => {
    setSelectedProject(project);
    setModalOpened(true);
  };

  return (
    <Box id="projects" style={{ padding: "4rem 0", backgroundColor: "var(--mantine-color-gray-1)" }}>
      <Container size="lg">
        <Stack align="center" style={{ marginBottom: "3rem" }}>
          <Title order={2} style={{ textAlign: "center", position: "relative" }}>
            Featured Projects
            <Box
              style={{
                position: "absolute",
                bottom: "-10px",
                left: "50%",
                transform: "translateX(-50%)",
                width: "60px",
                height: "4px",
                backgroundColor: "var(--mantine-color-purple-6)",
                borderRadius: "2px"
              }}
            />
          </Title>
          <Text c="gray.6" style={{ textAlign: "center", maxWidth: "600px" }}>
            A showcase of my technical work, from web applications to infrastructure tools. Each project represents a unique challenge solved.
          </Text>
        </Stack>

        <Group justify="center" gap="xs" style={{ marginBottom: "2rem", flexWrap: "wrap" }}>
          {categories.map((cat) => (
            <Button
              key={cat.value}
              variant={activeCategory === cat.value ? "filled" : "light"}
              color={activeCategory === cat.value ? "blue" : "gray"}
              size="sm"
              onClick={() => setActiveCategory(cat.value)}
            >
              {cat.label}
            </Button>
          ))}
        </Group>

        <SimpleGrid cols={{ base: 1, sm: 2, lg: 3 }} spacing="xl">
          {filteredProjects.map((project, index) => (
            <Box
              key={project.id}
              style={{
                transform: `translateY(${index % 2 === 0 ? "0" : "20px"})`,
                transition: "transform 0.3s ease"
              }}
            >
              <ProjectCard project={project} />
            </Box>
          ))}
        </SimpleGrid>

        <Modal
          opened={modalOpened}
          onClose={() => setModalOpened(false)}
          title={selectedProject?.title}
          size="lg"
          centered
        >
          {selectedProject && (
            <Stack gap="md">
              <Image
                src={selectedProject.image}
                alt={selectedProject.title}
                radius="md"
                style={{ maxHeight: "300px", objectFit: "cover" }}
              />
              <Text>{selectedProject.description}</Text>
              <Group gap="xs" style={{ flexWrap: "wrap" }}>
                {selectedProject.technologies.map((tech) => (
                  <Badge key={tech} variant="light" color="blue">
                    {tech}
                  </Badge>
                ))}
              </Group>
              <Group gap="sm">
                {selectedProject.liveUrl && (
                  <Button
                    leftSection={<IconExternalLink size={16} />}
                    onClick={() => window.open(selectedProject.liveUrl, "_blank", "noopener,noreferrer")}
                  >
                    Live Demo
                  </Button>
                )}
                {selectedProject.githubUrl && (
                  <Button
                    leftSection={<IconBrandGithub size={16} />}
                    variant="outline"
                    onClick={() => window.open(selectedProject.githubUrl, "_blank", "noopener,noreferrer")}
                  >
                    View on GitHub
                  </Button>
                )}
              </Group>
            </Stack>
          )}
        </Modal>
      </Container>
    </Box>
  );
};

export default ProjectsSection;
